  "description": "The tests every workflow needs and nobody writes, driven against a world its author supplies.",
  "type": "module",
  "license": "MIT",
  "author": "Nicolas Melo",
  "homepage": "https://github.com/nicolasmelo1/amy#readme",
  "bugs": "https://github.com/nicolasmelo1/amy/issues",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/nicolasmelo1/amy.git",
    "directory": "packages/workflow-testkit"
  },
  "publishConfig": {
    "access": "public",
    "registry": "https://registry.npmjs.org"
  },
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    }
  },
  "files": [
    "dist"
  ],
  "dependencies": {
    "@amykit/core": "^0.6.0"
  }
}

import { Plan, WorkRecord, applyPlan, looksIn, movedBy } from "@amykit/core";
import { Finding } from "./finding.js";
import { describe, replay, sameMove } from "./plans.js";
import { AnyWorkflow, Look, Walk, replayActions } from "./walk.js";

/**
 * Waiting is not trying.
 *
 * The core counts every look inside a state, waits included, because that is
 * what bounds a retry loop. A state that reads the same count to decide when
 * to give up has to be sure the looks it is counting were tries. Two ways it
 * goes wrong, and one probe each:
 *
 * - a declared waiting state that gives up after enough looks at a world that
 *   never changed: it is counting time as attempts;
 * - a state that held for a while and then got on with it, and would have done
 *   something else had the hold lasted longer: the hold was spent against the
 *   ceiling of the work that followed it. This is the one that escalated a
 *   ticket saying it had tried three times, having tried none.
 *
 * Both replay the same observation at the same instant on purpose. Holding
 * time still is what separates counting from waiting: a state that gives up on
 * a deadline keeps waiting here and passes, and only one that gives up because
 * the count grew goes red. Moving the clock would let a legitimate timeout
 * read as a wait counted as a try.
 */
export async function ceilings(workflow: AnyWorkflow, walks: readonly Walk[], extraLooks: number): Promise<Finding[]> {
  const findings: Finding[] = [];
  for (const walk of walks) {
    findings.push(...(await waitingStatesHold(workflow, walk, extraLooks)), ...holdsAreNotTries(workflow, walk, extraLooks));
  }
  return findings;
}

/**
 * Holds a waiting state for more looks at the same observation.
 *
 * Each held look is folded the way the walk folds one: the wait's own
 * actions are called and what they produced is applied, so a wait that
 * records something on its way — the moment it started, say — is replayed
 * as itself rather than as a bare count.
 */
async function waitingStatesHold(workflow: AnyWorkflow, walk: Walk, extraLooks: number): Promise<Finding[]> {
  const runtime = walk.runtime;
  if (!runtime) return [];
  const findings: Finding[] = [];
  const probed = new Set<string>();

  for (const look of walk.looks) {
    const state = look.record.state;
    if (look.plan.kind !== "wait" || !workflow.waitingStates.includes(state) || probed.has(state)) continue;
    probed.add(state);

    let record = look.record;
    let plan: Plan = look.plan;
    for (let count = 1; count <= extraLooks; count += 1) {
      const waited: Plan = plan;
      const before: WorkRecord = record;
      const outcomes = await replayActions(runtime, waited, before, look.observation, walk.port);
      if (!outcomes) break;
      const folded: WorkRecord | undefined = replay(() =>
        runtime.apply(applyPlan(before, waited, look.at, outcomes), waited, outcomes, look.observation, look.at, movedBy(before, waited)),
      );
      if (!folded) break;
      record = folded;
      const next: Plan | undefined = replay(() => workflow.plan(folded, look.observation, runtime.policy));
      if (!next) break;
      if (next.kind !== "wait") {
        findings.push({
          property: "ceilings",
          message:
            `${walk.world}: \`${state}\` is a waiting state, and after ${count} more look(s) at a world that had not ` +
            `changed it would ${describe(next)}. A look is not a try; give up on time, or on something the world said`,
        });
        break;
      }
      plan = next;
    }
  }
  return findings;
}

function holdsAreNotTries(workflow: AnyWorkflow, walk: Walk, extraLooks: number): Finding[] {
  const runtime = walk.runtime;
  if (!runtime) return [];
  const findings: Finding[] = [];

  for (const look of heldThenMoved(walk.looks)) {
    const state = look.record.state;
    const longer: WorkRecord = {
      ...look.record,
      looks: { ...(look.record.looks ?? look.record.attempts), [state]: looksIn(look.record, state) + extraLooks },
    };
    // Compared as moves, not word for word: an escalation whose reason
    // quotes the attempt count is the same decision with a different number
    // in it, and the question here is only whether the decision changed.
    const instead = replay(() => workflow.plan(longer, look.observation, runtime.policy));
    if (!instead || sameMove(look.plan, instead)) continue;
    findings.push({
      property: "ceilings",
      message:
        `${walk.world}: \`${state}\` held, then went on to ${describe(look.plan)}; had the hold lasted ` +
        `${extraLooks} look(s) longer it would ${describe(instead)} instead. The wait was counted as a try`,
    });
  }
  return findings;
}

/** The first look that did not wait, after one or more that did, without leaving the state in between. */
function heldThenMoved(looks: readonly Look[]): Look[] {
  const found: Look[] = [];
  for (let index = 1; index < looks.length; index += 1) {
    const before = looks[index - 1]!;
    const look = looks[index]!;
    if (before.plan.kind === "wait" && look.plan.kind !== "wait" && before.record.state === look.record.state) {
      found.push(look);
    }
  }
  return found;
}

import { Workflow, WorkRecord } from "@amykit/core";
import { ceilings } from "./ceilings.js";
import { escalation } from "./escalation.js";
import { Finding, PROPERTIES, Property, distinct } from "./finding.js";
import { folds } from "./folds.js";
import { handlers } from "./handlers.js";
import { reachability } from "./reachability.js";
import { transitions } from "./transitions.js";
import { AnyRuntime, AnyWorkflow, walk } from "./walk.js";
import { ConformanceOptions, World } from "./world.js";

/** A Thursday, so a roster that is only confirmed on workdays is confirmed. */
const THURSDAY_NOON = new Date("2026-09-03T12:00:00.000Z");

/**
 * Walks every world and asks the machine-shaped questions of what it saw.
 *
 * Returns what failed rather than throwing, so a caller can assert on one
 * finding; `conforms` is the version that becomes tests.
 */
export async function conformance<R extends WorkRecord, O, P, W extends World<R>>(
  workflow: Workflow<O, P>,
  options: ConformanceOptions<R, O, W>,
): Promise<Finding[]> {
  const machine = workflow as unknown as AnyWorkflow;
  if (options.worlds.length === 0) {
    return [{ property: "walk", message: "no world was given, so nothing was walked" }];
  }

  const walks = [];
  for (const world of options.worlds) {
    walks.push(
      await walk(machine, world, {
        runtime: (w, now) => options.runtime(w as W, now) as unknown as AnyRuntime,
        ports: (w) => options.ports?.(w as W) ?? {},
        maxLooks: options.maxLooks ?? 200,
        start: options.start ?? THURSDAY_NOON,
      }),
    );
  }

  const extraLooks = options.extraLooks ?? 10;
  const spent = await ceilings(machine, walks, extraLooks);
  return distinct([
    ...walks.flatMap((w) => w.findings),
    ...reachability(machine, walks),
    ...handlers(machine, walks),
    ...spent,
    ...folds(machine, walks),
    ...escalation(machine, walks, options.givesUp ?? []),
    ...transitions(machine, walks, options.everyEdge ?? false),
  ]).sort((a, b) => order(a.property) - order(b.property));
}

function order(property: Property): number {
  return Object.keys(PROPERTIES).indexOf(property);
}

import { Workflow, WorkRecord } from "@amykit/core";
import { conformance } from "./conformance.js";
import { ConformanceError } from "./errors.js";
import { Finding, PROPERTIES, Property } from "./finding.js";
import { ConformanceOptions, World } from "./world.js";

/**
 * The two functions every test runner has.
 *
 * Passed in rather than imported, so the suite runs in whatever the author
 * already uses — `node:test`, vitest, jest — and the kit depends on none of
 * them.
 */
export interface Runner {
  describe(name: string, body: () => void): unknown;
  it(name: string, body: () => Promise<void>): unknown;
}

export interface ConformsOptions<R extends WorkRecord, O, W extends World<R>> extends ConformanceOptions<R, O, W> {
  /** Left out, the runner's globals are used, for a runner that has them. */
  readonly runner?: Runner;
}

/**
 * Registers the machine-shaped suite as ordinary tests: one per property,
 * named for what it claims, red with every finding under it.
 *
 * The worlds are walked once, by whichever test runs first, and every test
 * reads the same report.
 */
export function conforms<R extends WorkRecord, O, P, W extends World<R>>(
  workflow: Workflow<O, P>,
  options: ConformsOptions<R, O, W>,
): void {
  const runner = options.runner ?? globalRunner();
  let report: Promise<Finding[]> | undefined;
  const findings = (): Promise<Finding[]> => (report ??= conformance(workflow, options));

  runner.describe(`${workflow.name} conforms to the machine`, () => {
    for (const property of Object.keys(PROPERTIES) as Property[]) {
      runner.it(PROPERTIES[property], async () => {
        const found = (await findings()).filter((finding) => finding.property === property);
        if (found.length > 0) throw new ConformanceError(property, found);
      });
    }
  });
}

function globalRunner(): Runner {
  const scope = globalThis as { describe?: Runner["describe"]; it?: Runner["it"] };
  if (typeof scope.describe === "function" && typeof scope.it === "function") {
    return { describe: scope.describe, it: scope.it };
  }
  throw new Error(
    "conforms needs a test runner: pass `runner: { describe, it }` from the one you use, " +
      'for example `import { describe, it } from "node:test"`',
  );
}

import { Finding, PROPERTIES, Property } from "./finding.js";

/** Thrown by one property's test, carrying every finding under it. */
export class ConformanceError extends Error {
  constructor(
    readonly property: Property,
    readonly findings: readonly Finding[],
  ) {
    super([`${PROPERTIES[property]}, and it did not:`, ...findings.map((f) => `  - ${f.message}`)].join("\n"));
    this.name = "ConformanceError";
  }
}

import { actionsOf } from "@amykit/core";
import { Finding } from "./finding.js";
import { AnyWorkflow, Walk } from "./walk.js";

/** The core's action for handing work to a person because the machine gave up. */
const ESCALATE = "escalate";

/**
 * A state the machine gives up into can be got out of, and only by something
 * that happened after it gave up.
 *
 * Two shapes. A giving-up state declared terminal is one nothing can ever get
 * work out of again, however the person answers. And a giving-up state left
 * on the very next look, before the world has moved at all, was left on
 * something that was already there — an answer from the day before, read as
 * the answer to a question asked a second ago — which is the escalation that
 * resumed, escalated and announced on a thirty-second cycle.
 *
 * Whether some world gets the work out at all is reachability's question,
 * asked of every state; this only asks what is particular to giving up.
 */
export function escalation(workflow: AnyWorkflow, walks: readonly Walk[], givesUp: readonly string[]): Finding[] {
  const states = givingUpStates(walks, givesUp);
  const findings: Finding[] = [];

  for (const state of states) {
    if (!workflow.states.includes(state)) {
      findings.push({ property: "escalation", message: `\`${state}\` is named in givesUp, and is not one of the states` });
    } else if (workflow.terminalStates.includes(state)) {
      findings.push({
        property: "escalation",
        message: `\`${state}\` is where the machine gives up, and it is terminal: nothing the person does can get the work out of it`,
      });
    }
  }

  for (const walk of walks) {
    const early = leftBeforeTheWorldMoved(walk, states);
    if (early) findings.push(early);
  }
  return findings;
}

/**
 * The first time this walk gave up and then left again with nothing having
 * happened in between. Only a giving-up the walk itself saw counts: a world
 * that starts in one may well have been answered long ago.
 */
function leftBeforeTheWorldMoved(walk: Walk, states: ReadonlySet<string>): Finding | undefined {
  let gaveUpInto: string | undefined;
  for (const look of walk.looks) {
    const plan = look.plan;
    if (plan.kind !== "advance") continue;
    if (look.record.state === gaveUpInto && !look.worldMoved) {
      return {
        property: "escalation",
        message:
          `${walk.world}: \`${gaveUpInto}\` moved to \`${plan.to}\` straight after giving up, before the world moved. ` +
          `It resumed on something that was already there, not on an answer`,
      };
    }
    gaveUpInto = states.has(plan.to) ? plan.to : undefined;
  }
  return undefined;
}

function givingUpStates(walks: readonly Walk[], givesUp: readonly string[]): Set<string> {
  const states = new Set(givesUp);
  for (const look of walks.flatMap((walk) => walk.looks)) {
    if (look.plan.kind === "advance" && actionsOf(look.plan).some((action) => action.type === ESCALATE)) {
      states.add(look.plan.to);
    }
  }
  return states;
}

/**
 * The machine-shaped half of a workflow, one property at a time.
 *
 * None of them is domain knowledge, which is why one kit can check every
 * workflow anybody will write. `walk` is the precondition for the others:
 * a world the runtime cannot even be driven through proves nothing else.
 */
export const PROPERTIES = {
  walk: "every world can be walked",
  reachability: "every state is reachable, and every state has a way out",
  handlers: "every action it plans has a handler that survives being called",
  ceilings: "a wait does not spend the ceiling that decides when to give up",
  folds: "an empty collection concludes nothing",
  escalation: "giving up has a way out, and only one",
  transitions: "every move is one the diagram draws",
} as const;

export type Property = keyof typeof PROPERTIES;

export interface Finding {
  readonly property: Property;
  /** Names the state, the action or the world, whichever the author has to go and look at. */
  readonly message: string;
}

/** The same finding from two worlds is one finding. */
export function distinct(findings: readonly Finding[]): Finding[] {
  const seen = new Set<string>();
  return findings.filter((finding) => {
    const key = `${finding.property}\u0000${finding.message}`;
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

export function message(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

import { Plan, WorkRecord } from "@amykit/core";
import { Finding } from "./finding.js";
import { describe, replay, sameDecision } from "./plans.js";
import { AnyWorkflow, Look, Walk } from "./walk.js";

/**
 * Nothing is concluded from an empty collection.
 *
 * `[].every(...)` is `true`, so a ticket with no repositories reads as
 * approved in all of them and gets merged in every one. The probe replays
 * each look with each collection it can find emptied, and asks whether the
 * decision rested on an `every` that had nothing to check: the same look is
 * decided twice, once with an empty `every` answering `true` as the language
 * does and once answering `false`, and a decision that changes between the
 * two was made by the vacuous truth rather than by the work.
 *
 * `!list.some(...)` is left alone on purpose. "None of them is open" is a
 * sentence that means something of none; "all of them are approved" is one
 * nobody means of none, and `every` is how that sentence is written.
 */
export function folds(workflow: AnyWorkflow, walks: readonly Walk[]): Finding[] {
  const findings: Finding[] = [];
  const reported = new Set<string>();

  for (const walk of walks) {
    const policy = walk.runtime?.policy;
    for (const look of walk.looks) {
      for (const variant of variantsOf(look)) {
        const decide = (): Plan => workflow.plan(variant.record, variant.observation, policy);
        const vacuous = decideWithEvery(true, decide);
        if (!vacuous.plan || !vacuous.asked) continue;
        const otherwise = decideWithEvery(false, decide);
        if (!otherwise.plan || sameDecision(vacuous.plan, otherwise.plan)) continue;

        const key = `${look.record.state}\u0000${variant.emptied}`;
        if (reported.has(key)) continue;
        reported.add(key);
        findings.push({
          property: "folds",
          message:
            `${walk.world}: in \`${look.record.state}\`, with ${variant.emptied}, the decision to ${describe(vacuous.plan)} ` +
            `rests on \`[].every(...)\` being true. Had there been anything to check it could have been ` +
            `${describe(otherwise.plan)}; say what an empty collection means instead of letting \`every\` say it`,
        });
      }
    }
  }
  return findings;
}

interface Variant {
  readonly record: WorkRecord;
  readonly observation: unknown;
  /** How the finding names what was emptied. */
  readonly emptied: string;
}

function variantsOf(look: Look): Variant[] {
  const variants: Variant[] = [{ record: look.record, observation: look.observation, emptied: "the collections as observed" }];
  const paths: string[][] = [];
  collections({ record: look.record, observation: look.observation }, [], paths, new Set());

  // Every collection, however deep and however many: a cap here would be a
  // collection the probe silently never emptied, and a green suite that
  // did not look.
  for (const path of paths) {
    const root = emptiedAt({ record: look.record, observation: look.observation }, path) as {
      record: WorkRecord;
      observation: unknown;
    };
    variants.push({ ...root, emptied: `\`${path.join(".")}\` empty` });
  }
  return variants;
}

/**
 * Every non-empty array reachable through plain objects and arrays, by every
 * path that reaches it.
 *
 * Only the chain being walked is remembered, and forgotten on the way back
 * up: an observation that refers back to itself stops at the loop, while one
 * array reachable as both `all` and `repos` is emptied under each name — the
 * plan may read either.
 */
function collections(value: unknown, path: string[], out: string[][], above: Set<object>): void {
  if (value === null || typeof value !== "object" || above.has(value)) return;
  const array = Array.isArray(value);
  if (!array && !isPlain(value)) return;

  above.add(value);
  if (array) {
    if (value.length > 0 && path.length > 0) out.push(path);
    value.forEach((item, index) => collections(item, [...path, String(index)], out, above));
  } else {
    for (const [key, item] of Object.entries(value)) collections(item, [...path, key], out, above);
  }
  above.delete(value);
}

function emptiedAt(value: unknown, path: readonly string[]): unknown {
  const [head, ...rest] = path;
  if (head === undefined) return [];
  if (Array.isArray(value)) {
    return value.map((item, index) => (String(index) === head ? emptiedAt(item, rest) : item));
  }
  return { ...(value as Record<string, unknown>), [head]: emptiedAt((value as Record<string, unknown>)[head], rest) };
}

function isPlain(value: unknown): value is Record<string, unknown> {
  if (value === null || typeof value !== "object") return false;
  const prototype = Object.getPrototypeOf(value) as unknown;
  return prototype === Object.prototype || prototype === null;
}

/**
 * Decides once with an empty `every` answering as told, and says whether any
 * `every` was asked of an empty array while deciding.
 *
 * The one place the kit reaches into the language: `plan` is synchronous and
 * pure, so for the length of one call nothing but `plan` runs, and whatever
 * `every` was in place — the language's, or somebody else's patch — is read
 * at the call and put back before it returns or throws.
 */
function decideWithEvery(answer: boolean, decide: () => Plan): { plan: Plan | undefined; asked: boolean } {
  const every = Array.prototype.every;
  let asked = false;
  const counted = function (this: unknown[], ...args: Parameters<typeof every>): boolean {
    if (this.length === 0) {
      asked = true;
      return answer;
    }
    return every.apply(this, args);
  };
  Array.prototype.every = counted as typeof every;
  try {
    const plan = replay(decide);
    return { plan, asked };
  } finally {
    Array.prototype.every = every;
  }
}

import { unrunnable } from "@amykit/core";
import { Finding } from "./finding.js";
import { AnyWorkflow, Walk } from "./walk.js";

/**
 * Every action the runtime declares has something behind it that could run.
 *
 * The walk already calls each action a plan carries, and refuses one the
 * runtime never declared. This is the half a walk cannot see: an action
 * declared for a step no world reached — the last step of the happy path,
 * say — is exactly the one that throws in production.
 */
export function handlers(_workflow: AnyWorkflow, walks: readonly Walk[]): Finding[] {
  const built = walks.filter((walk) => walk.runtime);
  const findings: Finding[] = [];
  const problems = new Map<string, { problem: string; worlds: string[] }>();

  // Every world builds its own runtime, and each is asked: a world whose
  // runtime drops an implementation, and never happens to plan that action,
  // would otherwise pass on the strength of another world's.
  for (const walk of built) {
    for (const [name, implementation] of Object.entries(walk.runtime!.actions)) {
      const problem = unrunnable(name, implementation, walk.port);
      if (!problem) continue;
      const seen = problems.get(problem) ?? { problem, worlds: [] };
      seen.worlds.push(walk.world);
      problems.set(problem, seen);
    }
  }

  for (const { problem, worlds } of problems.values()) {
    const whose = worlds.length === built.length ? "" : ` (in ${worlds.join(", ")})`;
    findings.push({ property: "handlers", message: `${problem}${whose}` });
  }
  return findings;
}

export { conformance } from "./conformance.js";
export { conforms } from "./conforms.js";
export { ConformanceError } from "./errors.js";
export type { ConformsOptions, Runner } from "./conforms.js";
export { PROPERTIES } from "./finding.js";
export type { Finding, Property } from "./finding.js";
export type { ConformanceOptions, World } from "./world.js";

import { Plan, actionsOf } from "@amykit/core";

/**
 * What a plan does, without why it says it does it.
 *
 * Two plans are the same move when they are the same kind, go to the same
 * state and carry the same actions. The prose differs between looks — "attempt
 * 2", "attempt 3" — and a comparison that read it would call every retry a
 * different decision.
 */
export function sameMove(a: Plan, b: Plan): boolean {
  return shape(a) === shape(b);
}

/**
 * Two plans are the same decision when everything but the prose matches: the
 * kind, the state, how long a wait holds, and every action with its payload.
 *
 * Stricter than `sameMove`, for a probe where a changed payload — the thread
 * ids handed to the agent, the person work is handed to — is a changed
 * decision in its own right.
 */
export function sameDecision(a: Plan, b: Plan): boolean {
  return canonical(withoutWhy(a)) === canonical(withoutWhy(b));
}

function withoutWhy(plan: Plan): unknown {
  const { why: _why, ...rest } = plan;
  return rest;
}

/** JSON with object keys in a stable order, so two equal payloads print the same. */
function canonical(value: unknown): string {
  return JSON.stringify(value, (_key, item: unknown) =>
    item !== null && typeof item === "object" && !Array.isArray(item)
      ? Object.fromEntries(Object.entries(item as Record<string, unknown>).sort(([a], [b]) => a.localeCompare(b)))
      : item,
  );
}

function shape(plan: Plan): string {
  const to = plan.kind === "advance" ? plan.to : "";
  return `${plan.kind}:${to}:${actionsOf(plan).map((action) => action.type).join(",")}`;
}

/** A plan as a person reads it in a finding. */
export function describe(plan: Plan): string {
  const actions = actionsOf(plan).map((action) => `\`${action.type}\``);
  const carrying = actions.length > 0 ? ` with ${actions.join(", ")}` : "";
  switch (plan.kind) {
    case "advance":
      return `move to \`${plan.to}\`${carrying}`;
    case "act":
      return `act${carrying}`;
    case "wait":
      return `wait${carrying}`;
    case "settled":
      return "settle";
  }
}

/**
 * A decision the kit asks for on its own account, replaying a look.
 *
 * A replay that throws is not what the probe is about — the walk already
 * reports a plan that throws on a look the world really produced — so it is
 * treated as no answer rather than as a finding.
 */
export function replay<T>(body: () => T): T | undefined {
  try {
    return body();
  } catch {
    return undefined;
  }
}

import { Finding } from "./finding.js";
import { AnyWorkflow, Walk } from "./walk.js";

/**
 * Every declared state is reached by some world, and every state that is not
 * terminal is left by some world.
 *
 * Reached means the machine got there itself: from `newRecord`, or by moving.
 * A world that *starts* a record in a state proves nothing about whether the
 * machine can arrive in it, so it does not count.
 */
export function reachability(workflow: AnyWorkflow, walks: readonly Walk[]): Finding[] {
  const seen = tally(workflow, walks);
  const findings: Finding[] = [...declarationProblems(workflow), ...seen.findings];

  for (const state of workflow.states) {
    if (!seen.reached.has(state)) {
      findings.push({ property: "reachability", message: `\`${state}\` is declared, and no world reaches it` });
    } else if (!workflow.terminalStates.includes(state) && seen.planned.has(state) && !seen.left.has(state)) {
      findings.push({
        property: "reachability",
        message: `nothing leaves \`${state}\`: every world that reaches it leaves the work there`,
      });
    }
  }
  return findings;
}

interface Tally {
  readonly reached: Set<string>;
  readonly left: Set<string>;
  readonly planned: Set<string>;
  readonly findings: Finding[];
}

/** Which states the walks arrived in, planned in and moved out of, and which settled where they should not have. */
function tally(workflow: AnyWorkflow, walks: readonly Walk[]): Tally {
  const seen: Tally = { reached: new Set(), left: new Set(), planned: new Set(), findings: [] };
  if (walks.some((walk) => walk.fromTheStart)) seen.reached.add(workflow.initialState);

  for (const look of walks.flatMap((walk) => walk.looks)) {
    const state = look.record.state;
    seen.planned.add(state);
    if (look.plan.kind === "advance") {
      seen.reached.add(look.plan.to);
      if (look.plan.to !== state) seen.left.add(state);
    }
    lanesIn(workflow, look.record, seen);
    const terminal = workflow.terminalStates.includes(state);
    if (look.plan.kind === "settled" && !terminal) {
      seen.findings.push({ property: "reachability", message: `\`${state}\` settles, and is not declared terminal` });
    } else if (look.plan.kind !== "settled" && terminal) {
      seen.findings.push({ property: "reachability", message: `\`${state}\` is terminal, and planning it does not settle` });
    }
  }
  return seen;
}

/**
 * A lane is never a record's state: the record waits in the fork. So a lane
 * is reached when the fork started it, and left when its own record ended.
 */
function lanesIn(workflow: AnyWorkflow, record: Walk["looks"][number]["record"], seen: Tally): void {
  const fork = workflow.diagram?.forks[record.state];
  for (const lane of fork?.lanes ?? []) {
    const call = record.lanes?.[lane]?.call;
    const child = call === undefined ? undefined : record.calls?.[call];
    if (!child) continue;
    seen.reached.add(lane);
    seen.planned.add(lane);
    if (workflow.calls?.[lane]?.terminalStates.includes(child.state)) seen.left.add(lane);
  }
}

function declarationProblems(workflow: AnyWorkflow): Finding[] {
  const named: [string, readonly string[]][] = [
    ["initialState", [workflow.initialState]],
    ["terminalStates", workflow.terminalStates],
    ["waitingStates", workflow.waitingStates],
  ];

  return named.flatMap(([field, names]) =>
    names
      .filter((name) => !workflow.states.includes(name))
      .map((name): Finding => ({ property: "reachability", message: `\`${name}\` is named in ${field}, and is not one of the states` })),
  );
}

import { DrawnTransition, WorkRecord, Workflow, cameFrom, connects } from "@amykit/core";
import { Finding } from "./finding.js";
import { AnyWorkflow, Walk } from "./walk.js";

/**
 * Every move a world made is one the diagram connects, and — when asked —
 * every arrow it draws is a move some world made.
 *
 * A workflow with no diagram has nothing to be held to, and passes. A move
 * out of a `returns` state is connected when it goes back to where the record
 * came from, and any state that is not terminal may move to an `anywhere`
 * one, because that is what those classes say.
 */
export function transitions(workflow: AnyWorkflow, walks: readonly Walk[], everyEdge: boolean): Finding[] {
  const diagram = workflow.diagram;
  if (!diagram) return [];

  const findings: Finding[] = [];
  for (const walk of walks) {
    for (const { record, plan } of walk.looks) {
      if (plan.kind !== "advance") continue;
      if (connects(diagram, record.state, plan.to, cameFrom(record.history, record.state))) continue;
      findings.push({
        property: "transitions",
        message: `${walk.world}: \`${record.state}\` moves to \`${plan.to}\`, and the diagram draws no arrow from \`${record.state}\` to \`${plan.to}\``,
      });
    }
    for (const child of callsIn(workflow, walk)) {
      if (!child.workflow.diagram) continue;
      child.record.history.forEach((move, index) => {
        if (connects(child.workflow.diagram!, move.from, move.to, cameFrom(child.record.history.slice(0, index), move.from))) return;
        findings.push({
          property: "transitions",
          message: `${walk.world}: in the call \`${child.at}\`, \`${move.from}\` moves to \`${move.to}\`, and ${child.workflow.name}'s diagram draws no arrow from \`${move.from}\` to \`${move.to}\``,
        });
      });
    }
  }
  if (!everyEdge) return findings;

  const lanes = lanesDrawn(workflow as Workflow, "");
  return [
    ...findings,
    ...drawnNotWalked(workflow, walks).map((edge): Finding => ({
      property: "transitions",
      message: `\`${edge.from}\` → \`${edge.to}\`${lanes.has(edge.from) && edge.label ? ` (\`${edge.label}\`)` : ""} is drawn, and no world walks it`,
    })),
  ];
}

/**
 * The arrows the diagram draws that no walk took: for a workflow still being
 * written, the to-do list. A called workflow's arrows count too, named by the
 * call state they sit in (`REVIEW/READING`), walked when its record moved
 * along them.
 */
function drawnNotWalked(workflow: AnyWorkflow, walks: readonly Walk[]): DrawnTransition[] {
  const root = workflow as Workflow;
  const walked = new Set(
    walks.flatMap((walk) => walk.looks)
      .filter((look) => look.plan.kind === "advance")
      .map((look) => `${look.record.state}\u0000${(look.plan as { to: string }).to}`),
  );
  for (const walk of walks) {
    for (const child of callsIn(workflow, walk)) {
      for (const move of child.record.history) walked.add(`${child.at}/${move.from}\u0000${child.at}/${move.to}`);
    }
    for (const look of walk.looks) for (const edge of laneEdges(root, look.record, "")) walked.add(edge);
  }
  const seen = new Set<string>();
  // Every end of a lane leads to the same join, so the end is what tells one
  // of those arrows from another.
  const lanes = lanesDrawn(root, "");
  return drawn(workflow, "").filter((edge) => {
    const key = lanes.has(edge.from) ? `${edge.from}\u0000${edge.to}\u0000${edge.label ?? ""}` : `${edge.from}\u0000${edge.to}`;
    if (walked.has(key) || seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

/**
 * The arrows a record waiting in a fork has walked: from the fork into every
 * lane it started, and from each lane that ended into the join.
 */
function laneEdges(workflow: Workflow, record: WorkRecord, prefix: string): string[] {
  const fork = workflow.diagram?.forks[record.state];
  const own = (fork?.lanes ?? []).flatMap((lane) => {
    const call = record.lanes?.[lane]?.call;
    const child = call === undefined ? undefined : record.calls?.[call];
    if (!child) return [];
    const ended = workflow.calls?.[lane]?.terminalStates.includes(child.state);
    return [`${prefix}${record.state}\u0000${prefix}${lane}`, ...(ended ? [`${prefix}${lane}\u0000${prefix}${fork!.join}\u0000${child.state}`] : [])];
  });
  // A callee's own forks, at every depth, named by the call state they sit in.
  const nested = Object.values(record.calls ?? {}).flatMap((child) => {
    const state = /\/([A-Za-z_]\w*)#\d+$/.exec(child.id)?.[1];
    const callee = state ? workflow.calls?.[state] : undefined;
    return state && callee ? laneEdges(callee, child, `${prefix}${state}/`) : [];
  });
  return [...own, ...nested];
}

/** Every lane drawn, at every depth, named as `drawn` names it. */
function lanesDrawn(workflow: Workflow, prefix: string): Set<string> {
  const own = Object.values(workflow.diagram?.forks ?? {}).flatMap((fork) => fork.lanes.map((lane) => `${prefix}${lane}`));
  const nested = Object.entries(workflow.calls ?? {}).flatMap(([state, callee]) => [...lanesDrawn(callee, `${prefix}${state}/`)]);
  return new Set([...own, ...nested]);
}

function drawn(workflow: Workflow, prefix: string): DrawnTransition[] {
  const own = (workflow.diagram?.transitions ?? []).map((edge) => ({ ...edge, from: `${prefix}${edge.from}`, to: `${prefix}${edge.to}` }));
  return [...own, ...Object.entries(workflow.calls ?? {}).flatMap(([state, callee]) => drawn(callee, `${prefix}${state}/`))];
}

interface Called {
  /** The call states it was reached through, as `REVIEW/FIX`. */
  readonly at: string;
  readonly workflow: Workflow;
  readonly record: WorkRecord;
}

/**
 * Every call a walk made, at any depth, each as the longest history any look
 * saw it with: a child keeps its own, so the last look holds every move.
 */
function callsIn(workflow: AnyWorkflow, walk: Walk): Called[] {
  const latest = new Map<string, Called>();
  const visit = (caller: Workflow, record: WorkRecord, prefix: string): void => {
    for (const child of Object.values(record.calls ?? {})) {
      const state = /\/([A-Za-z_]\w*)#\d+$/.exec(child.id)?.[1];
      const callee = state ? caller.calls?.[state] : undefined;
      if (!state || !callee) continue;
      const at = `${prefix}${state}`;
      const known = latest.get(child.id);
      if (!known || known.record.history.length < child.history.length) latest.set(child.id, { at, workflow: callee, record: child });
      visit(callee, child, `${at}/`);
    }
  };
  for (const look of walk.looks) visit(workflow as Workflow, look.record, "");
  return [...latest.values()];
}

import {
  Plan,
  PortLookup,
  Workflow,
  WorkflowRuntime,
  WorkRecord,
  actionsOf,
  applyPlan,
  implementationOf,
  movedBy,
  notATryIn,
  runAction,
  undeclaredIn,
} from "@amykit/core";
import { Finding, Property, message } from "./finding.js";
import { Clock, World } from "./world.js";

/** The engine holds a refunded look for its retry delay; the walk names one. */
const REFUNDED_HOLD_MS = 60_000;

/** The workflow and its runtime with their types let go of, which is all a walk needs. */
export type AnyWorkflow = Workflow<unknown, unknown>;
export type AnyRuntime = WorkflowRuntime<WorkRecord, unknown>;

/** One look the machine took: what it saw, and what it decided. */
export interface Look {
  readonly record: WorkRecord;
  readonly observation: unknown;
  readonly plan: Plan;
  /** The kit's clock when the look was taken. */
  readonly at: Date;
  /** Whether any `meanwhile` ran since the record entered the state it is in. */
  readonly worldMoved: boolean;
}

export interface Walk {
  readonly world: string;
  /** The runtime this world was walked with, for the probes that replay a look. */
  readonly runtime: AnyRuntime | undefined;
  /** The ports this world hands an action wired as a port and a method. */
  readonly port: PortLookup;
  /** True when the record came from the runtime's own `newRecord`. */
  readonly fromTheStart: boolean;
  readonly looks: readonly Look[];
  readonly findings: readonly Finding[];
}

export interface WalkOptions {
  readonly runtime: (world: World, now: () => Date) => AnyRuntime;
  readonly ports: (world: World) => Readonly<Record<string, object>>;
  readonly maxLooks: number;
  readonly start: Date;
}

/**
 * Drives one world the way the engine drives a queue item, one look at a
 * time, until the work settles, waits with nothing left to happen, fails, or
 * spins.
 *
 * Every action a plan carries is *called*, against the observation the
 * runtime really built. That is the difference between this and asking
 * whether a handler exists: a handler that reads a field the observation no
 * longer has exists, and throws on the first real piece of work.
 */
export async function walk(workflow: AnyWorkflow, world: World, options: WalkOptions): Promise<Walk> {
  const clock = new Clock(options.start);
  const findings: Finding[] = [];
  const looks: Look[] = [];
  const fail = (property: Property, said: string): void => {
    findings.push({ property, message: `${world.name}: ${said}` });
  };
  const ports = attempt(() => options.ports(world), (error) => fail("walk", `the ports could not be built — ${error}`)) ?? {};
  const port: PortLookup = (kind) => (Object.hasOwn(ports, kind) ? ports[kind] : undefined);
  const done = (runtime: AnyRuntime | undefined, fromTheStart: boolean): Walk => ({
    world: world.name, runtime, port, fromTheStart, looks, findings,
  });

  const runtime = attempt(() => options.runtime(world, clock.now), (error) => fail("walk", `the runtime could not be built — ${error}`));
  if (!runtime) return done(undefined, false);

  const fromTheStart = !world.start;
  const record = attempt(
    () => world.start?.(clock.now()) ?? runtime.newRecord(world.workId ?? world.name, clock.now()),
    (error) => fail("walk", `the first record could not be made — ${error}`),
  );
  if (!record) return done(runtime, fromTheStart);
  if (fromTheStart && record.state !== workflow.initialState) {
    fail("reachability", `newRecord starts at \`${record.state}\`, not at the initial state \`${workflow.initialState}\``);
  }

  await drive(workflow, runtime, record, { world, clock, looks, fail, port, maxLooks: options.maxLooks });
  return done(runtime, fromTheStart);
}

interface Drive {
  readonly world: World;
  readonly clock: Clock;
  readonly looks: Look[];
  readonly fail: (property: Property, said: string) => void;
  readonly port: PortLookup;
  readonly maxLooks: number;
}

/** The looks themselves, from the first record until the walk comes to rest. */
async function drive(workflow: AnyWorkflow, runtime: AnyRuntime, first: WorkRecord, walk: Drive): Promise<void> {
  const pending = [...(walk.world.meanwhile ?? [])];
  let record = first;
  let worldMoved = false;

  for (let count = 0; count < walk.maxLooks; count += 1) {
    const look = await lookOnce(workflow, runtime, record, { ...walk, worldMoved });
    if (!look) return;
    walk.looks.push(look.look);
    const plan = look.look.plan;
    if (plan.kind === "settled") return;

    if (look.next.state !== record.state) worldMoved = false;
    record = look.next;

    if (look.holdMs === undefined) {
      walk.clock.pass(1000);
      continue;
    }
    // The world only moves while the machine waits, and only as far as the
    // author said it would. A wait with nothing left to happen is where this
    // world ends, which is not a failure: it is a question for the other
    // worlds, whether any of them gets the work out of here.
    const next = pending.shift();
    if (!next) return;
    walk.clock.pass(look.holdMs);
    if (!(await meanwhile(next, walk.fail))) return;
    worldMoved = true;
  }

  walk.fail("reachability", `did not come to rest within ${walk.maxLooks} looks; it was last in \`${record.state}\``);
}

async function meanwhile(step: () => void | Promise<void>, fail: (property: Property, said: string) => void): Promise<boolean> {
  try {
    await step();
    return true;
  } catch (error) {
    fail("walk", `a \`meanwhile\` step threw — ${message(error)}`);
    return false;
  }
}

async function lookOnce(
  workflow: AnyWorkflow,
  runtime: AnyRuntime,
  record: WorkRecord,
  { clock, worldMoved, fail, port }: Drive & { worldMoved: boolean },
): Promise<{ look: Look; next: WorkRecord; holdMs?: number } | undefined> {
  const at = clock.now();
  let observation: unknown;
  try {
    observation = await runtime.observe(record);
  } catch (error) {
    fail("walk", `observing \`${record.state}\` threw — ${message(error)}`);
    return undefined;
  }

  const plan = attempt(
    () => workflow.plan(record, observation, runtime.policy),
    (error) => fail("walk", `planning \`${record.state}\` threw — ${error}`),
  );
  if (!plan) return undefined;
  const look: Look = { record, observation: snapshot(observation), plan, at, worldMoved };

  if (plan.kind === "advance" && !workflow.states.includes(plan.to)) {
    fail("reachability", `\`${record.state}\` moves to \`${plan.to}\`, which the workflow does not declare`);
    return undefined;
  }

  const outcomes = await run(runtime, look, observation, fail, port);
  if (!outcomes) return undefined;
  if (plan.kind === "settled") return { look, next: record };

  const next = attempt(
    () => runtime.apply(applyPlan(record, plan, at, outcomes), plan, outcomes, observation, at, movedBy(record, plan)),
    (error) => fail("walk", `folding a look in \`${record.state}\` threw — ${error}`),
  );
  return next ? { look, next, holdMs: holdOf(plan, outcomes) } : undefined;
}

/** A wait holds, and so does a look whose outcome says it was never a try. */
function holdOf(plan: Plan, outcomes: Record<string, unknown>): number | undefined {
  if (plan.kind === "wait") return plan.retryAfterMs;
  const refunded = plan.kind === "act" ? notATryIn(outcomes) : undefined;
  return refunded ? (refunded.retryAfterMs ?? REFUNDED_HOLD_MS) : undefined;
}

/** Calls every action a plan carries, the way the engine would, and keeps what they produced. */
async function run(
  runtime: AnyRuntime,
  look: Look,
  observation: unknown,
  fail: (property: Property, said: string) => void,
  port: PortLookup,
): Promise<Record<string, unknown> | undefined> {
  const outcomes: Record<string, unknown> = {};
  const state = look.record.state;

  // The whole plan first, as the engine does, so an undeclared action is
  // reported with nothing ahead of it already run.
  const [undeclared] = undeclaredIn(runtime, look.plan);
  if (undeclared) {
    fail("handlers", `\`${state}\` plans \`${undeclared}\`, which the runtime never declares in its actions`);
    return undefined;
  }

  for (const action of actionsOf(look.plan)) {
    try {
      await runAction(implementationOf(runtime, action.type), action, { record: look.record, observation, outcomes }, port);
    } catch (error) {
      fail("handlers", `\`${action.type}\` threw when \`${state}\` called it — ${message(error)}`);
      return undefined;
    }
  }
  return outcomes;
}

/**
 * Calls a plan's actions again, for a probe that replays a look, and returns
 * what they produced — or nothing, when one is missing or throws. The walk has
 * already reported either of those on the look it really took.
 */
export async function replayActions(
  runtime: AnyRuntime,
  plan: Plan,
  record: WorkRecord,
  observation: unknown,
  port: PortLookup,
): Promise<Record<string, unknown> | undefined> {
  const outcomes: Record<string, unknown> = {};
  if (undeclaredIn(runtime, plan).length > 0) return undefined;
  for (const action of actionsOf(plan)) {
    try {
      await runAction(implementationOf(runtime, action.type), action, { record, observation, outcomes }, port);
    } catch {
      return undefined;
    }
  }
  return outcomes;
}

/**
 * The observation as it was when the look was taken, for the probes that
 * replay it.
 *
 * A fake port may hand back the very object a `meanwhile` goes on to change,
 * and a look replayed later has to see what the machine saw then, not what
 * the world became. The walk itself decides and acts on the observation it
 * was given; only a replay reads the copy, and one that cannot be copied —
 * it carries a function — is kept as it is.
 */
function snapshot(observation: unknown): unknown {
  try {
    return structuredClone(observation);
  } catch {
    return observation;
  }
}

function attempt<T>(body: () => T, failed: (error: string) => void): T | undefined {
  try {
    return body();
  } catch (error) {
    failed(message(error));
    return undefined;
  }
}

import { WorkflowRuntime, WorkRecord } from "@amykit/core";

/**
 * One situation the machine is put in, supplied by whoever wrote the workflow.
 *
 * The kit never invents one. It drives the author's own runtime against the
 * author's own ports, because a harness that stubs the domain proves the
 * stub: a fake that ignored the argument the real port maps over once let a
 * handler hand it `undefined` and still go green.
 *
 * A world is walked once per conformance run, so one that keeps state — a
 * fake tracker that remembers the comment it was given — is built fresh for
 * each run rather than shared between them.
 */
export interface World<R extends WorkRecord = WorkRecord> {
  /** Named in every finding, so a red test says which situation broke. */
  readonly name: string;
  /**
   * The id `newRecord` is given, for a runtime that resolves it against a
   * port — a ticket id the fake tracker knows, a note the notes directory
   * holds. Left out, the world's name.
   */
  readonly workId?: string;
  /**
   * The record the walk starts from. Left out, the runtime's own `newRecord`
   * makes it, which is the only start that proves a state reachable from the
   * beginning.
   */
  readonly start?: (now: Date) => R;
  /**
   * What the outside world does while the machine waits, in order: somebody
   * answers, a reviewer reviews, a checkout frees up.
   *
   * One runs each time the machine waits, and never otherwise — so a state
   * that moves on without one of these having run moved on something that
   * was already there.
   */
  readonly meanwhile?: readonly (() => void | Promise<void>)[];
}

export interface ConformanceOptions<R extends WorkRecord, O, W extends World<R>> {
  /**
   * The workflow's own runtime, over the fake ports a world carries.
   *
   * `now` is the kit's clock. Ports that stamp anything — an answer, a gate
   * run — read it, so the record and the world agree on what happened first.
   */
  readonly runtime: (world: W, now: () => Date) => WorkflowRuntime<R, O>;
  readonly worlds: readonly W[];
  /**
   * The ports an action declared as a port and a method is called on, by
   * kind — the fakes a world carries, handed over the way the host hands
   * over the mounted ones. Left out, no port is mounted, and an action wired
   * that way is reported as having nothing behind it.
   */
  readonly ports?: (world: W) => Readonly<Record<string, object>>;
  /**
   * States where the machine has given up and handed the work to a person.
   *
   * A state entered by an `escalate` action is one already, without being
   * named here. This is for a workflow that gives up some other way.
   */
  readonly givesUp?: readonly string[];
  /**
   * Whether an arrow the diagram draws and no world walks is a failure.
   *
   * Off, a move the diagram does not draw still fails, and an arrow nobody
   * walked is only the to-do list of a workflow still being written. On, for
   * a finished workflow whose worlds walk every arrow it draws.
   */
  readonly everyEdge?: boolean;
  /** How many looks one world may take before it is called a spin. Default 200. */
  readonly maxLooks?: number;
  /**
   * How many more looks a wait is held for when the kit asks whether waiting
   * is being counted as trying. Default 10, which is past every attempt
   * ceiling either shipped workflow sets.
   */
  readonly extraLooks?: number;
  /** When the clock starts. Default a Thursday noon, UTC. */
  readonly start?: Date;
}

/** The time a walk runs at. It only moves when the kit moves it. */
export class Clock {
  private at: number;

  constructor(start: Date) {
    this.at = start.getTime();
  }

  readonly now = (): Date => new Date(this.at);

  pass(ms: number): void {
    this.at += ms;
  }
}
